={{ (() => {
  const body = $('Webhook').first().json.body || {};
  let criteria = {};
  try { criteria = typeof body.criteria === 'string' ? JSON.parse(body.criteria) : (body.criteria || {}); } catch (e) {}

  const position = body.position || criteria.position || '';
  const location = body.location || criteria.location || '';
  const notes = criteria.query || '';
  const ns = 'Not specified';

  // The analysis is ALWAYS produced in English; "Apply CV Localization" downstream
  // renders it in Arabic when the requester's locale is Arabic.
  const summary = criteria.optionsSummaryEn || criteria.optionsSummaryAr || '';

  const job = [
    'Position: ' + (position || ns),
    'Location: ' + (location || ns),
    criteria.yearsOfExperience ? 'Years of experience: ' + criteria.yearsOfExperience : '',
    criteria.ageRange ? 'Age range: ' + criteria.ageRange : '',
    notes ? 'Notes: ' + notes : '',
    summary,
  ].filter(Boolean).join('\n');

  const directive = 'OUTPUT_LANGUAGE = en\nWrite every human-readable field (summary, strengths, weaknesses, education, recommendation, comparisonSummary) in English only, even if the CVs or the job requirements below are written in Arabic.';

  const cvTexts = $input.first().json.text;
  return directive + '\n\nJob requirements:\n' + job + '\n\nCVs to compare (extracted text):\n' + JSON.stringify(cvTexts, null, 2);
})() }}

