const item = $input.first();
const binaries = item.binary || {};
const body = item.json.body || {};

const keys = Object.keys(binaries)
  .filter((k) => /^cvs\d*$/i.test(k) || k === 'cvs')
  .sort((a, b) => {
    const na = parseInt(a.replace(/\D/g, ''), 10);
    const nb = parseInt(b.replace(/\D/g, ''), 10);
    if (Number.isFinite(na) && Number.isFinite(nb)) return na - nb;
    return a.localeCompare(b);
  });

if (!keys.length) {
  throw new Error('No CV PDF binaries found (expected cvs0, cvs1, …)');
}

return keys.map((key) => ({
  json: {
    fileName: binaries[key].fileName || key,
    comparisonId: body.comparisonId,
    position: body.position,
    location: body.location,
    criteria: body.criteria,
    callbackUrl: body.callbackUrl,
  },
  binary: {
    data: binaries[key],
  },
}));

const agentOut = $input.first().json;
let raw = agentOut.output ?? agentOut.text ?? agentOut.response ?? agentOut;
let parsed = {};

if (typeof raw === 'string') {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try { parsed = JSON.parse(raw.slice(start, end + 1)); } catch (e) { parsed = {}; }
  }
} else if (raw && typeof raw === 'object') {
  if (raw.candidates) parsed = raw;
  else if (raw.parsed && typeof raw.parsed === 'object') parsed = raw.parsed;
  else if (typeof raw.output === 'string') {
    const start = raw.output.indexOf('{');
    const end = raw.output.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try { parsed = JSON.parse(raw.output.slice(start, end + 1)); } catch (e) { parsed = {}; }
    }
  }
}

const candidates = Array.isArray(parsed.candidates) ? parsed.candidates : [];
const webhook = $('Webhook').first().json.body || {};
const fileNames = $('Prepare CV Binaries').all().map((i) => i.json.fileName);

const comparisons = candidates.map((c, idx) => ({
  fileName: c.name || fileNames[idx] || `CV ${idx + 1}`,
  name: c.name || fileNames[idx] || `CV ${idx + 1}`,
  rank: idx + 1,
  score: c.overallScore ?? c.score ?? null,
  matchScore: c.overallScore ?? c.score ?? null,
  summary: c.summary || (Array.isArray(c.strengths) ? c.strengths.join('; ') : '') || '',
  skills: Array.isArray(c.skills) ? c.skills : [],
  experienceYears: c.experienceYears ?? null,
  education: c.education || '',
  strengths: Array.isArray(c.strengths) ? c.strengths : [],
  weaknesses: Array.isArray(c.weaknesses) ? c.weaknesses : [],
}));

// Display locale for the result. An explicit locale from the backend wins; otherwise
// detect it from what the USER typed - never from the CV text (analysis is English now).
let _criteria = {};
try { _criteria = typeof webhook.criteria === 'string' ? JSON.parse(webhook.criteria) : (webhook.criteria || {}); } catch (e) {}
const _explicit = String(webhook.language || webhook.locale || _criteria.language || '').trim().toLowerCase();
let targetLang = _explicit.indexOf('ar') === 0 ? 'ar' : (_explicit.indexOf('en') === 0 ? 'en' : '');
if (!targetLang) {
  const _sample = [
    webhook.position || _criteria.position || '',
    webhook.location || _criteria.location || '',
    _criteria.query || '',
    _criteria.optionsSummaryAr || '',
  ].join(' ');
  const _ar = (_sample.match(/[\u0600-\u06FF]/g) || []).length;
  const _lat = (_sample.match(/[A-Za-z]/g) || []).length;
  targetLang = (_ar >= 2 && _ar >= _lat) ? 'ar' : 'en';
}

return [{
  json: {
    targetLang,
    comparisonId: webhook.comparisonId,
    callbackUrl: webhook.callbackUrl,
    comparisons,
    candidates,
    ranking: parsed.ranking || [],
    recommendation: parsed.recommendation || '',
    comparisonSummary: parsed.comparisonSummary || '',
  },
}];

const item = $input.first();
const body = item.json.body ?? {};

const reject = (reason) => [{
  json: { passed: false, rejectReason: reason, body },
  binary: item.binary,
}];

if (!String(body.comparisonId || '').trim()) {
  return reject('Missing comparisonId');
}
if (!String(body.callbackUrl || '').trim()) {
  return reject('Missing callbackUrl');
}
if (!String(body.position || '').trim()) {
  return reject('Missing position');
}
if (!String(body.location || '').trim()) {
  return reject('Missing location');
}
if (!String(body.inboundSecret || '').trim()) {
  return reject('Missing inboundSecret');
}

return [{
  json: { passed: true, rejectReason: '', body },
  binary: item.binary,
}];

const item = $input.first();
const prev = item.json;
if (!prev.passed) {
  return [{ json: prev, binary: item.binary }];
}

const body = prev.body || {};
const urlStr = String(body.callbackUrl || '').trim();

const reject = (reason) => [{
  json: { passed: false, rejectReason: reason, body },
  binary: item.binary,
}];

if (!urlStr) {
  return reject('Missing callbackUrl');
}

if (urlStr.includes('@') || /\/redirect\//i.test(urlStr)) {
  return reject('Redirect or credential URLs are not allowed');
}

const m = urlStr.match(/^(https?):\/\/([^\/?#:]+)(?::(\d+))?(\/[^?#]*)?(?:\?([^#]*))?/i);
if (!m) {
  return reject('Invalid callbackUrl');
}

const scheme = String(m[1] || '').toLowerCase();
const host = String(m[2] || '');
let port = m[3] ? String(m[3]) : '';
const pathname = m[4] || '/';
const query = m[5] || '';

if (host.includes('*')) {
  return reject('Wildcard hostnames are not allowed');
}

if (!port) {
  port = scheme === 'https' ? '443' : '80';
}

let origin;
if (scheme === 'https' && port === '443') {
  origin = 'https://' + host;
} else if (scheme === 'http' && port === '80') {
  origin = 'http://' + host;
} else {
  origin = scheme + '://' + host + ':' + port;
}

const allowed = [
  'https://api.evaalo.com',
  'http://100.73.82.78:5000',
];

let ok = false;
for (let i = 0; i < allowed.length; i++) {
  if (allowed[i] === origin) {
    ok = true;
    break;
  }
}

if (!ok) {
  return reject('callbackUrl origin not allowlisted: ' + origin);
}

if (pathname !== '/webhook/n8n/cv-comparison') {
  return reject('callbackUrl path must be /webhook/n8n/cv-comparison');
}

let hasComparisonId = false;
let hasToken = false;
if (query) {
  const parts = query.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const eq = part.indexOf('=');
    const k = eq >= 0 ? decodeURIComponent(part.slice(0, eq)) : part;
    const v = eq >= 0 ? decodeURIComponent(part.slice(eq + 1)) : '';
    if (k === 'comparisonId' && String(v).trim()) hasComparisonId = true;
    if (k === 'token' && String(v).trim()) hasToken = true;
  }
}

if (!hasComparisonId) {
  return reject('callbackUrl must include comparisonId query parameter');
}
if (!hasToken) {
  return reject('callbackUrl must include token query parameter');
}

return [{
  json: { passed: true, rejectReason: '', body },
  binary: item.binary,
}];

// Merge the Arabic translation back onto the English result.
// Any parse/shape failure falls back to the English text rather than breaking the callback.
const base = $('Format Comparison Results').first().json;
const targetLang = base.targetLang || 'en';

const fallback = () => [{ json: base }];
if (targetLang === 'en') return fallback();

function parseJsonLoose(raw) {
  if (raw == null) return null;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return null;
  let s = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) s = s.slice(a, b + 1);
  try { return JSON.parse(s); } catch (e) { return null; }
}

const item = $input.first().json;
let t = parseJsonLoose(item.output ?? item.text ?? item.response ?? item);
if (t && t.output && typeof t.output === 'object') t = t.output;
if (!t || typeof t !== 'object' || !Array.isArray(t.comparisons)) return fallback();

const str = (v, fb) => (typeof v === 'string' && v.trim()) ? v : fb;
// Length equality is required: a shorter array means the model dropped a point.
const arr = (v, fb) => (Array.isArray(fb) && Array.isArray(v) && v.length === fb.length)
  ? v.map((x, i) => str(x, fb[i]))
  : fb;

const byRank = new Map();
for (const c of t.comparisons) byRank.set(Number(c && c.rank), c);

const comparisons = (base.comparisons || []).map((c) => {
  const tr = byRank.get(Number(c.rank));
  if (!tr) return c;
  return {
    ...c,
    summary: str(tr.summary, c.summary),
    education: str(tr.education, c.education),
    strengths: arr(tr.strengths, c.strengths),
    weaknesses: arr(tr.weaknesses, c.weaknesses),
  };
});

// candidates[] mirrors comparisons by position - keep both in sync for the backend contract.
const candidates = (base.candidates || []).map((cand, idx) => {
  const c = comparisons[idx];
  if (!c) return cand;
  return { ...cand, summary: c.summary, education: c.education, strengths: c.strengths, weaknesses: c.weaknesses };
});

return [{
  json: {
    ...base,
    comparisons,
    candidates,
    recommendation: str(t.recommendation, base.recommendation),
    comparisonSummary: str(t.comparisonSummary, base.comparisonSummary),
  },
}];
